class Solution {
public:
    void moveZeroes(vector<int>& a) {
        int write = 0;
        for (int read = 0; read < (int)a.size(); read++) {
            if (a[read] != 0) {
                swap(a[write], a[read]);
                write++;
            }
        }
    }
};
