class Solution {
public:
    vector<int> sortArrayByParity(vector<int>& a) {
        int write = 0;
        for (int read = 0; read < (int)a.size(); read++)
            if (a[read] % 2 == 0) swap(a[write++], a[read]);
        return a;
    }
};
