class Solution {
public:
    vector<int> applyOperations(vector<int>& a) {
        int n = a.size();
        for (int i = 0; i + 1 < n; i++)
            if (a[i] == a[i + 1]) { a[i] *= 2; a[i + 1] = 0; }
        int write = 0;
        for (int read = 0; read < n; read++)
            if (a[read] != 0) swap(a[write++], a[read]);
        return a;
    }
};
